const body = $input.first().json.body || $input.first().json;

const docType = body.documentType || 'Fire Safety Certificate';
const expiryDate = body.expiryDate || null;
const appId = body.applicationId || 'AICTE-DEMO';

// Mandatory regulatory keywords checklist
const checklist = {
  'Fire Safety Certificate': ['fire', 'safety', 'department', 'noc', 'certificate', 'valid'],
  'Occupancy or Building Completion Certificate': ['completion', 'occupancy', 'building', 'engineer', 'municipal'],
  'Structural Stability Certificate': ['structural', 'stability', 'load', 'safety', 'engineer']
};

const expected = checklist[docType] || ['certificate', 'valid', 'authority'];

// Evaluate pre-screening confidence
const confidence = expiryDate ? 95 : 60;
const status = confidence >= 80 ? 'OCR Verified - Pending Human Scrutiny' : 'OCR Flagged - Missing Fields';

return [{
  json: {
    documentId: body.documentId || 'DOC-' + Date.now(),
    applicationId: appId,
    documentType: docType,
    expiryDate: expiryDate,
    confidenceScore: confidence,
    status: status,
    disclaimer: 'Pre-screening heuristic only. Does not replace statutory physical scrutiny by AICTE committee.',
    processedAt: new Date().toISOString()
  }
}];
